// The public skill file (Sess ledger L-125; founder 2026-11-26 22:18Z item 3(b)):
// skills/ask-a-person-with-sess/SKILL.md holds the bytes production serves at
// https://sess.si/.well-known/agent-skills/ask-a-person-with-sess/SKILL.md, generated by the Sess
// site build (apps/site/scripts/agent-skill.ts), never typed by hand. This check reads production
// with two public GETs and no secret: the discovery index beside the skill (its `digest` is the
// sha256 of the served bytes) and the served file itself. Both must equal this copy.
//
// Before production serves the skill (the `agent-skill` feature is listed for the preview only
// until a Sess release PR lists it for production), both addresses answer 404 and the check
// skips, saying so. From the moment either one is published, any difference fails: an index that
// lists the skill with a missing file or another digest, or a served file with other bytes. Any
// other status, a redirect, an unreadable index or a network error fails too: an outcome that
// cannot be read is never a pass.
//
// Usage: node scripts/check-skill.mjs   Self-test: node --test scripts/test-check-skill.mjs
// To refresh the copy, build the Sess site with the production origins and the production
// feature set plus agent-skill, and copy apps/site/dist/.well-known/agent-skills/<name>/SKILL.md.
import { createHash } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

export const SKILL_NAME = 'ask-a-person-with-sess';
export const SKILL_PATH = `skills/${SKILL_NAME}/SKILL.md`;
export const ORIGIN = 'https://sess.si';
export const INDEX_URL = `${ORIGIN}/.well-known/agent-skills/index.json`;
export const SKILL_URL = `${ORIGIN}/.well-known/agent-skills/${SKILL_NAME}/SKILL.md`;

const DIGEST = /^sha256:[0-9a-f]{64}$/;

/** sha256 of some bytes, as the discovery index writes it. */
export function digestOf(bytes) {
  return `sha256:${createHash('sha256').update(bytes).digest('hex')}`;
}

/** One GET: { status, bytes }. No redirect is followed; no cache is used. */
async function get(fetchImpl, url) {
  const res = await fetchImpl(url, {
    redirect: 'manual',
    cache: 'no-store',
    headers: { 'cache-control': 'no-cache' },
  });
  const bytes = Buffer.from(await res.arrayBuffer());
  return { status: res.status, bytes };
}

/**
 * Compare the local copy with what production serves.
 * @param {{ local: Buffer, fetch?: typeof globalThis.fetch }} opts
 * @returns {Promise<{ outcome: 'skip' | 'match' | 'fail', lines: string[] }>}
 */
export async function checkSkill({ local, fetch: fetchImpl = globalThis.fetch }) {
  const want = digestOf(local);
  const problems = [];
  const [index, served] = [await get(fetchImpl, INDEX_URL), await get(fetchImpl, SKILL_URL)];

  // The index: 404 (not published), or 200 with an entry for the skill or without one.
  let listed;
  if (index.status === 200) {
    let doc;
    try {
      doc = JSON.parse(index.bytes.toString('utf8'));
    } catch {
      problems.push(`${INDEX_URL}: not JSON`);
    }
    if (doc !== undefined) {
      const skills = Array.isArray(doc?.skills) ? doc.skills : undefined;
      if (!skills) problems.push(`${INDEX_URL}: no skills array`);
      listed = skills?.find((s) => s?.name === SKILL_NAME);
      if (listed) {
        if (listed.type !== 'skill-md') problems.push(`${INDEX_URL}: ${SKILL_NAME} type is ${listed.type}`);
        if (listed.url !== SKILL_URL) problems.push(`${INDEX_URL}: ${SKILL_NAME} url is ${listed.url}`);
        if (typeof listed.digest !== 'string' || !DIGEST.test(listed.digest))
          problems.push(`${INDEX_URL}: ${SKILL_NAME} has no sha256 digest`);
        else if (listed.digest !== want)
          problems.push(`${INDEX_URL}: ${SKILL_NAME} digest is ${listed.digest}, ${SKILL_PATH} is ${want}`);
      }
    }
  } else if (index.status !== 404) {
    problems.push(`${INDEX_URL}: answered ${index.status}, expected 200 or 404`);
  }

  // The served file: 404 only while the index does not list it; 200 with exactly these bytes.
  if (served.status === 200) {
    const got = digestOf(served.bytes);
    if (got !== want) problems.push(`${SKILL_URL}: serves ${got}, ${SKILL_PATH} is ${want}`);
  } else if (served.status === 404) {
    if (listed) problems.push(`${SKILL_URL}: answered 404, but the index lists ${SKILL_NAME}`);
  } else {
    problems.push(`${SKILL_URL}: answered ${served.status}, expected 200 or 404`);
  }

  if (problems.length) return { outcome: 'fail', lines: problems };
  if (served.status === 404)
    return {
      outcome: 'skip',
      lines: [
        `skipped: production does not serve ${SKILL_NAME} yet (${SKILL_URL} answered 404; ` +
          `the index ${index.status === 404 ? 'answered 404' : 'does not list it'}). ` +
          `${SKILL_PATH} is ${want}; the check compares bytes once production publishes the skill.`,
      ],
    };
  return {
    outcome: 'match',
    lines: [
      `${SKILL_PATH} matches production: ${want}, served at ${SKILL_URL}` +
        (listed ? ' and listed in the index.' : ' (the index does not list it).'),
    ],
  };
}

/** Network errors are retried twice; a status is never retried away. */
async function withRetries(run, attempts = 3) {
  for (let i = 1; ; i += 1) {
    try {
      return await run();
    } catch (err) {
      if (i >= attempts) throw err;
      await new Promise((r) => setTimeout(r, 2000 * i));
    }
  }
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const local = await readFile(SKILL_PATH);
  let result;
  try {
    result = await withRetries(() => checkSkill({ local }));
  } catch (err) {
    console.error(`could not read production: ${err?.cause?.code ?? err?.message ?? err}`);
    process.exit(1);
  }
  const out = result.outcome === 'fail' ? console.error : console.log;
  for (const line of result.lines) out(line);
  if (result.outcome === 'fail') {
    console.error(`${SKILL_PATH} differs from production. Regenerate it from the Sess site build.`);
    process.exit(1);
  }
}
